/* Paper & Ink · full palette from Design Lounge by Susan Acharya (acharyasusan.com.np)
   Primary / secondary / tertiary + feedback + surfaces. Match the numbers.
   Free to use. A credit link is appreciated: https://acharyasusan.com.np */
:root {
  /* Brand */
  --primary: #a8661a;
  --primary-ink: #fffdf8;
  --primary-soft: #e9dcc9;
  --secondary: #3f6b4a;
  --secondary-ink: #fffdf8;
  --secondary-soft: #daddd0;
  --tertiary: #3d4f6b;
  --tertiary-ink: #fffdf8;
  --tertiary-soft: #dad9d5;

  /* Surface */
  --bg: #f3efe6;
  --surface: #eae5d9;
  --surface-2: #e0dacb;
  --surface-3: #d4cec0;
  --ink: #171512;
  --ink-2: #5b564e;
  --ink-3: #8c867b;
  --line: #d6cfc0;
  --line-strong: #8d887e;

  /* Feedback — reserved for live state, never decoration */
  --success: #3f6b4a;
  --success-ink: #fffdf8;
  --success-soft: #daddd0;
  --warning: #b45309;
  --warning-ink: #fffdf8;
  --warning-soft: #ead9c7;
  --danger: #9b2c2c;
  --danger-ink: #fffdf8;
  --danger-soft: #e7d4cc;
  --info: #3d4f6b;
  --info-ink: #fffdf8;
  --info-soft: #dad9d5;

  /* Chrome */
  --focus: #a8661a;
  --link: #975c17;
  --overlay: #141210;
  --inverse: #171512;
  --inverse-ink: #f3efe6;

  /* Aliases */
  --accent: var(--primary);
  --accent-ink: var(--primary-ink);
  --positive: var(--success);

  --font-display: "Fraunces", Georgia, serif;
  --font-text: "Instrument Sans", system-ui, sans-serif;
  --radius: 4px;
  --shadow: 0 12px 32px -12px rgba(23,21,18,.25);
}
body {
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-text);
}
h1, h2, h3, .display { font-family: var(--font-display); }

