  --font-text: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
}
h1, h2, h3, .display {
  font-family: var(--font-display);
  font-weight: 400;
  letter-spacing: -0.025em;
  line-height: 1;
}
body {
  font-family: var(--font-text);
  font-weight: 400;
  line-height: 1.55;
}

/* Lettera · type pairing from Design Lounge by Susan Acharya (acharyasusan.com.np) */
@import url("https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400..900;1,400..900&family=Karla:wght@400;500;700&display=swap");

:root {
  --font-display: "Playfair Display", Georgia, "Times New Roman", serif;
  --font-text: "Karla", "Helvetica Neue", Arial, sans-serif;
}
h1, h2, h3, .display {
  font-family: var(--font-display);
  font-weight: 500;
  font-style: italic;
  letter-spacing: -0.02em;
  line-height: 1;
}
body {
  font-family: var(--font-text);
  font-weight: 400;
  line-height: 1.55;
}

/* Pixel Soft · type pairing from Design Lounge by Susan Acharya (acharyasusan.com.np) */
