/* Geometric Modern · type pairing from Design Lounge by Susan Acharya (acharyasusan.com.np) */
@import url("https://fonts.googleapis.com/css2?family=Sora:wght@400;600;800&display=swap");

:root {
  --font-display: "Sora", "Helvetica Neue", Arial, sans-serif;
